import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"The captain's message","description":"Remember to contribute 2 to save 64. The measured leverage — the two coins per commercial use fund saving up to the seal's 64 two-bit verifications. Integrity, not truth.","frontmatter":{"title":"The captain's message","description":"Remember to contribute 2 to save 64. The measured leverage — the two coins per commercial use fund saving up to the seal's 64 two-bit verifications. Integrity, not truth."},"headers":[],"relativePath":"docs/captain/message.md","filePath":"docs/captain/message.md"}`),a={name:`docs/captain/message.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-captain-s-message" tabindex="-1">The captain&#39;s message <a class="header-anchor" href="#the-captain-s-message" aria-label="Permalink to “The captain&#39;s message”">​</a></h1><blockquote><p>free on the free sailing angle; prize earning in waves — contribute 2 to earn up to 64 per wave, keep the rest</p></blockquote><p>Given by the captain, recorded as receipt <code>85ac8585-9dc1-8964-9848-ae0f49cc82fb</code> — the content-address of the message itself, gate-passed. This is its canonical home: <strong>uuidna.com/captain/message</strong>. Refined in the open (full lineage on the <a href="https://github.com/ceccec/millennium-solutions" target="_blank" rel="noreferrer">millennium-solutions captain page</a> — append-only, nothing hidden).</p><h2 id="the-double-torus-—-earth-navigation" tabindex="-1">The double torus — earth navigation <a class="header-anchor" href="#the-double-torus-—-earth-navigation" aria-label="Permalink to “The double torus — earth navigation”">​</a></h2><p>The captain navigates the double torus, a genus-2 surface: χ = 2 − 2·2 = −2, so <strong>−χ = 2</strong> — the two coins are the topology, not a price from air. Navigation lands on integer positions (no decimal drift): the harmonic bearings 30·{1,2,3} = {30,60,90}, digital roots {3,6,9}, centre 40 = harmonicMean(30,60). Earth&#39;s navigation is sexagesimal (60′/degree) — resonating with the 60° gold string.</p><h2 id="the-two-angles" tabindex="-1">The two angles <a class="header-anchor" href="#the-two-angles" aria-label="Permalink to “The two angles”">​</a></h2><ul><li><strong>Free sailing angle</strong> — off the wind (≥ 90°), the wind carries you: free (non-commercial).</li><li><strong>Prize earning waves</strong> — the beating band 30°–60°, each leap folding and sending the next (O(log N), compounding).</li></ul><h2 id="why-—-the-measured-leverage-per-wave" tabindex="-1">Why — the measured leverage, per wave <a class="header-anchor" href="#why-—-the-measured-leverage-per-wave" aria-label="Permalink to “Why — the measured leverage, per wave”">​</a></h2><ul><li><strong>Contribute 2.</strong> The two coins — 110 − 108 = 2 = −χ(genus-2) — the conserved invariant; the 2 bits each membership check costs.</li><li><strong>Earn up to 64.</strong> A seal is a fixed 128 bits = 64 two-bit fold-verifications; folding is O(log N) (1024 leaves fold to one root in 10 levels). Up to 64, conditional on the re-addressable work — never a universal discount. Keep the rest: the contributor keeps up to 62; the captain earns the conserved 2, and zero with no saving. Fair, bounded.</li><li><strong>Obligatory vs not.</strong> The contribution is obligatory for commercial use (the two coins, the measured bit difference). The donation is not — voluntary support, a gift, never a revenue promise (realized cash $0).</li></ul><h2 id="why-it-is-reminded-everywhere" tabindex="-1">Why it is reminded everywhere <a class="header-anchor" href="#why-it-is-reminded-everywhere" aria-label="Permalink to “Why it is reminded everywhere”">​</a></h2><p>The contribution block is fused under every page of the work; the reminder rides with it, so the reason is present at the exact point of contribution, linked here where anyone can recompute the address and read it unaltered. A content-address proves integrity, not truth.</p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};